    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    markers = []
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if g[r][c] == 2 and all(g[rr][cc] == 3 for rr in range(r-1, r+2) for cc in range(c-1, c+2) if (rr, cc) != (r, c)):
                markers.append((r, c))
    for r, c in markers:
        vertical = ((r-2 >= 0 and g[r-2][c] == 2) or (r+2 < h and g[r+2][c] == 2))
        horizontal = ((c-2 >= 0 and g[r][c-2] == 2) or (c+2 < w and g[r][c+2] == 2))
        # The guide line through the marker determines the perpendicular ray.
        if vertical and not horizontal:
            points = [(r, x) for x in range(w)]
        elif horizontal and not vertical:
            points = [(y, c) for y in range(h)]
        elif vertical:
            points = [(r, x) for x in range(w)]
        else:
            points = [(y, c) for y in range(h)]
        for y, x in points:
            if g[y][x] == 0:
                g[y][x] = 1
        # At each crossing with another guide line, form a 3x3 junction.
        for y, x in points:
            if (y, x) == (r, c) or g[y][x] != 2:
                continue
            for yy in range(max(0, y-1), min(h, y+2)):
                for xx in range(max(0, x-1), min(w, x+2)):
                    if (yy, xx) != (y, x) and g[yy][xx] != 3:
                        g[yy][xx] = 1
    return g
'''
